INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, content, metadata_json, created_at) VALUES ('earp-bruce-medical-necessity-and-consent-jme-2023', 'Earp Bruce Medical necessity and consent JME 2023', 'Published Canon: Medical Policy & Bioethics', '/documents/earp-bruce-medical-necessity-and-consent-jme-2023.pdf', 'medical_journal', 'ingested', 'Earp BD, Bruce L. J Med Ethics September 2023 Vol 49 No 9
